export const RenderHLogo: React.FC<{ yearCode: string; className?: string; fillColor?: string }> = ({
  yearCode,
  className = 'w-full h-full',
  fillColor = '#FFFFFF'
}) => {
  const normalized = yearCode.replace(/[^0-9]/g, '');
  const suffix = normalized.length === 4 ? normalized.slice(2) : normalized;

  switch (suffix) {
    case '16':
      return <H16 className={className} fillColor={fillColor} />;
    case '17':
      return <H17 className={className} fillColor={fillColor} />;
    case '18':
      return <H18 className={className} fillColor={fillColor} />;
    case '19':
      return <H19 className={className} fillColor={fillColor} />;
    case '20':
      return <H20 className={className} fillColor={fillColor} />;
    case '21':
      return <H21 className={className} fillColor={fillColor} />;
    case '22':
      return <H22 className={className} fillColor={fillColor} />;
    case '23':
      return <H23 className={className} fillColor={fillColor} />;
    case '24':
      return <H24 className={className} fillColor={fillColor} />;
    case '25':
      return <H25 className={className} fillColor={fillColor} />;
    case '26':
      return <H26 className={className} fillColor={fillColor} />;
    case '27':
      return <H27 className={className} fillColor={fillColor} />;
    default:
      return <H26 className={className} fillColor={fillColor} />;
  }
};
